-- apicc 元数据 H2 库初始化脚本（规格 m3 §2 D5/D6）。
-- 约束：
--   1. 全部使用幂等 DDL（CREATE TABLE IF NOT EXISTS），配合 spring.sql.init.mode=always 每次启动执行；
--   2. 当前支持 H2；加法升级使用其幂等 DDL，不宣称已支持其他数据库；
--   3. 主键取型（裁定 A，规格 2026-09-09 BIGINT 化）：实体主键为 BIGINT——
--      GENERATED BY DEFAULT AS IDENTITY（默认数据库自增；BY DEFAULT 容外部策略显式携 id 插入）；
--      对外 JSON/URL 一律字符串化数字（Java 全链 Long，View 层 String.valueOf 出参）；
--      关联表用自然复合主键（tokens/memberships/project_acl/file_versions），
--      其中的实体引用列（workspace_id/project_id/group_id 等）同为 BIGINT（批 3 任务 3 收口）；
--   4. 时间戳列（裁定 B）：一律 TIMESTAMP WITH TIME ZONE 存绝对时刻，写入统一经 OffsetDateTime(UTC)，
--      读取以 OffsetDateTime → Instant 还原；API 序列化形状（ISO-8601 UTC）由任务 3-5 契约测试钉住；
--   5. 角色列：VARCHAR + CHECK IN（可移植写法），枚举外脏值在库层拦下；
--   6. F7f 采用保留数据的加法升级；列先增加，授权回填通过持久标记只执行一次。

-- 账号（规格 §3.1：bcrypt 哈希入库，服务端不存明文密码；§2：role/disabled 支撑账号管家）
CREATE TABLE IF NOT EXISTS users (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY,
    username      VARCHAR(32)  NOT NULL,
    password_hash VARCHAR(100) NOT NULL,
    display_name  VARCHAR(64)  NOT NULL,
    role          VARCHAR(16)  NOT NULL DEFAULT 'USER',
    disabled      BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT uk_users_username UNIQUE (username),
    CONSTRAINT ck_users_role CHECK (role IN ('USER','SUPERADMIN'))
);

-- 认证令牌（规格 §2 D4：不透明 Bearer token，仅存 SHA-256 哈希；token_hash 即自然主键）
CREATE TABLE IF NOT EXISTS tokens (
    token_hash VARCHAR(64)  NOT NULL,
    user_id    BIGINT       NOT NULL,
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    revoked    BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_tokens PRIMARY KEY (token_hash)
);

-- 团队工作区（规格 §3.2；内容随 file_versions.content 入库，规格 §5——磁盘内容树已退役）
-- 规格 2026-09-08 §1：首启自动建唯一「默认工作区」；name 全局唯一（并发安全靠唯一约束）
CREATE TABLE IF NOT EXISTS workspaces (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY,
    name       VARCHAR(64) NOT NULL,
    created_by BIGINT      NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_workspaces PRIMARY KEY (id),
    CONSTRAINT uk_workspaces_name UNIQUE (name)
);

-- 工作区成员角色（规格 §2 D5 第一层：OWNER > ADMIN > EDITOR > VIEWER）
CREATE TABLE IF NOT EXISTS memberships (
    workspace_id BIGINT      NOT NULL,
    user_id      BIGINT      NOT NULL,
    role         VARCHAR(16) NOT NULL CHECK (role IN ('OWNER','ADMIN','EDITOR','VIEWER')),
    created_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_memberships PRIMARY KEY (workspace_id, user_id)
);

-- 项目级 ACL 覆盖（规格 §2 D5 第二层：NONE/VIEWER/EDITOR/ADMIN；无行 = 继承工作区角色）
CREATE TABLE IF NOT EXISTS project_acl (
    workspace_id BIGINT      NOT NULL,
    project_id   BIGINT      NOT NULL,
    user_id      BIGINT      NOT NULL,
    role         VARCHAR(16) NOT NULL CHECK (role IN ('NONE','VIEWER','EDITOR','ADMIN')),
    updated_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_project_acl PRIMARY KEY (workspace_id, project_id, user_id)
);

-- F7f ACL metadata: additive on the supported H2 database, without replacing role rows.
ALTER TABLE project_acl ADD COLUMN IF NOT EXISTS state VARCHAR(32) NOT NULL DEFAULT 'active';
ALTER TABLE project_acl ADD COLUMN IF NOT EXISTS revision BIGINT NOT NULL DEFAULT 1;
ALTER TABLE project_acl ADD COLUMN IF NOT EXISTS membership_epoch BIGINT NOT NULL DEFAULT 0;
ALTER TABLE project_acl ADD COLUMN IF NOT EXISTS actor_id BIGINT;
CREATE TABLE IF NOT EXISTS access_members (
    workspace_id BIGINT NOT NULL, user_id BIGINT NOT NULL, revision BIGINT NOT NULL,
    PRIMARY KEY(workspace_id,user_id)
);
CREATE TABLE IF NOT EXISTS access_policy_scopes (
    workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL, revision BIGINT NOT NULL,
    PRIMARY KEY(workspace_id,project_id)
);
CREATE TABLE IF NOT EXISTS access_capability_defaults (
    workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL, code VARCHAR(64) NOT NULL, mode VARCHAR(16) NOT NULL,
    PRIMARY KEY(workspace_id,project_id,code)
);
CREATE TABLE IF NOT EXISTS access_member_capabilities (
    workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL, user_id BIGINT NOT NULL,
    code VARCHAR(64) NOT NULL, mode VARCHAR(16) NOT NULL,
    PRIMARY KEY(workspace_id,project_id,user_id,code)
);
ALTER TABLE users ADD COLUMN IF NOT EXISTS state_revision BIGINT NOT NULL DEFAULT 1;
ALTER TABLE access_members ADD COLUMN IF NOT EXISTS membership_epoch BIGINT NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS access_project_epochs (
    workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL, user_id BIGINT NOT NULL,
    responsibility_epoch BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY(workspace_id,project_id,user_id)
);
ALTER TABLE access_project_epochs ADD COLUMN IF NOT EXISTS sync_check_epoch BIGINT NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS access_mutation_gate(id BIGINT PRIMARY KEY);
-- Authorization generations must not contend with long-lived project content locks.
CREATE TABLE IF NOT EXISTS access_project_generations (
    workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL, revision BIGINT NOT NULL,
    PRIMARY KEY(workspace_id,project_id)
);
INSERT INTO access_mutation_gate(id) SELECT 1 WHERE NOT EXISTS(SELECT 1 FROM access_mutation_gate WHERE id=1);
CREATE TABLE IF NOT EXISTS access_audit (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    actor_id BIGINT NOT NULL,workspace_id BIGINT,project_id BIGINT,user_id BIGINT,revision BIGINT NOT NULL,
    action VARCHAR(64) NOT NULL,reason_code VARCHAR(64) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL
);
CREATE TABLE IF NOT EXISTS access_schema_migrations(name VARCHAR(64) PRIMARY KEY);

-- 文件版本行 = 元数据 + 内容正文（规格 §2 D6 + §5：每 (workspace, path) 一份；version 从 1 起，
-- 乐观并发以 UPDATE ... WHERE version = ? 单条 SQL 原子递增；version 仅供并发比对，不追溯历史）
CREATE TABLE IF NOT EXISTS file_versions (
    workspace_id BIGINT       NOT NULL,
    path         VARCHAR(512) NOT NULL,
    content_hash VARCHAR(64)  NOT NULL,
    version      BIGINT       NOT NULL,
    updated_by   BIGINT       NOT NULL,
    updated_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    content      CLOB,
    CONSTRAINT pk_file_versions PRIMARY KEY (workspace_id, path),
    CONSTRAINT ck_file_versions_version CHECK (version >= 1)
);

-- 分组（规格 2026-09-08 §4）：同工作区内名称唯一；默认分组 name='默认分组' 不可删改
CREATE TABLE IF NOT EXISTS groups (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY,
    workspace_id BIGINT      NOT NULL,
    name         VARCHAR(64) NOT NULL,
    is_default   BOOLEAN     NOT NULL DEFAULT FALSE,
    created_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_groups PRIMARY KEY (id),
    CONSTRAINT uk_groups_ws_name UNIQUE (workspace_id, name)
);

-- 项目（规格 §4）：允许同名（身份=id）；挂分组；内容树按项目挂载
CREATE TABLE IF NOT EXISTS projects (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY,
    workspace_id BIGINT      NOT NULL,
    group_id     BIGINT      NOT NULL,
    name         VARCHAR(64) NOT NULL,
    created_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_projects PRIMARY KEY (id),
    CONSTRAINT fk_projects_group FOREIGN KEY (group_id) REFERENCES groups(id)
);

-- groups 增默认分组标记（seeder/create 落 TRUE；改名/删除守卫判据）
-- ALTER 仅服务既有库兼容（新库 CREATE TABLE 已含 is_default；未发布阶段口径=删库重开，此处双保险）
ALTER TABLE groups ADD COLUMN IF NOT EXISTS is_default BOOLEAN NOT NULL DEFAULT FALSE;

-- file_versions 扩内容列（规格 §5 内容入库）：一行 = 元数据 + 字节（CLOB/PG text）
-- ALTER 形态（幂等：H2 支持 ADD COLUMN IF NOT EXISTS；新库走 CREATE TABLE 已含）：
ALTER TABLE file_versions ADD COLUMN IF NOT EXISTS content CLOB;

-- Explicit publication only; existing rows retain their original bytes.
ALTER TABLE projects ADD COLUMN IF NOT EXISTS asset_format VARCHAR(32);
ALTER TABLE projects ADD COLUMN IF NOT EXISTS contract_project_id VARCHAR(36);
ALTER TABLE projects ADD COLUMN IF NOT EXISTS asset_version BIGINT NOT NULL DEFAULT 0;

-- Preserve existing active member roles and explicit NONE; dormant positive presets require confirmation.
INSERT INTO access_members(workspace_id,user_id,revision,membership_epoch)
    SELECT m.workspace_id,m.user_id,1,0 FROM memberships m
    WHERE NOT EXISTS(SELECT 1 FROM access_members a WHERE a.workspace_id=m.workspace_id AND a.user_id=m.user_id)
      AND NOT EXISTS(SELECT 1 FROM access_schema_migrations WHERE name='access-v1');
UPDATE project_acl a SET state='pending-confirmation'
    WHERE a.role<>'NONE' AND a.state='active'
      AND NOT EXISTS(SELECT 1 FROM memberships m WHERE m.workspace_id=a.workspace_id AND m.user_id=a.user_id)
      AND NOT EXISTS(SELECT 1 FROM access_schema_migrations WHERE name='access-v1');
INSERT INTO access_schema_migrations(name) SELECT 'access-v1'
    WHERE NOT EXISTS(SELECT 1 FROM access_schema_migrations WHERE name='access-v1');

-- No update operation: immutable definition bytes survive subsequent source edits/deletes.
CREATE TABLE IF NOT EXISTS execution_snapshots (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    workspace_id BIGINT NOT NULL,
    project_id BIGINT NOT NULL,
    created_by BIGINT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    assets_json CLOB NOT NULL,
    CONSTRAINT pk_execution_snapshots PRIMARY KEY (id)
);

-- Agent identities are separate from users and from project execution authorization.
CREATE TABLE IF NOT EXISTS execution_agents (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(128) NOT NULL,
    accepting_jobs BOOLEAN NOT NULL DEFAULT TRUE,
    revoked BOOLEAN NOT NULL DEFAULT FALSE,
    identity_hash VARCHAR(64),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS execution_agent_enrollments (
    token_hash VARCHAR(64) PRIMARY KEY, agent_id BIGINT NOT NULL, created_by BIGINT NOT NULL,
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL, used_at TIMESTAMP WITH TIME ZONE
);
CREATE TABLE IF NOT EXISTS execution_agent_workspace_grants (
    agent_id BIGINT NOT NULL, workspace_id BIGINT NOT NULL, PRIMARY KEY(agent_id,workspace_id)
);
CREATE TABLE IF NOT EXISTS execution_agent_project_allocations (
    agent_id BIGINT NOT NULL, workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL, PRIMARY KEY(agent_id,project_id)
);
CREATE TABLE IF NOT EXISTS execution_project_agents (
    project_id BIGINT NOT NULL, agent_id BIGINT NOT NULL, PRIMARY KEY(project_id,agent_id)
);
CREATE TABLE IF NOT EXISTS execution_project_settings (
    project_id BIGINT PRIMARY KEY, default_agent_id BIGINT
);
CREATE TABLE IF NOT EXISTS execution_configs (
    scope_type VARCHAR(16) NOT NULL, scope_id BIGINT NOT NULL, version BIGINT NOT NULL DEFAULT 0,
    config_json CLOB NOT NULL, applied_version BIGINT NOT NULL DEFAULT 0,
    pending_fields_json CLOB NOT NULL DEFAULT '[]', restart_fields_json CLOB NOT NULL DEFAULT '[]',
    PRIMARY KEY(scope_type,scope_id)
);
CREATE TABLE IF NOT EXISTS execution_script_grants (
    agent_id BIGINT NOT NULL, workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL,
    version BIGINT NOT NULL, grant_scope VARCHAR(32) NOT NULL, scripts_json CLOB NOT NULL,
    granted_by BIGINT NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY(agent_id,project_id)
);
CREATE TABLE IF NOT EXISTS execution_management_audit (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id BIGINT NOT NULL,
    action VARCHAR(64) NOT NULL, scope_type VARCHAR(16) NOT NULL, scope_id BIGINT NOT NULL,
    version BIGINT, agent_id BIGINT, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
-- Historical rows have no recoverable target; do not invent one when extending an existing database.
ALTER TABLE execution_management_audit ADD COLUMN IF NOT EXISTS agent_id BIGINT;
-- T5 typed asset facts; historical events stay unknown rather than acquiring invented classification.
ALTER TABLE execution_management_audit ADD COLUMN IF NOT EXISTS asset_locations_json CLOB;
ALTER TABLE execution_management_audit ADD COLUMN IF NOT EXISTS asset_summary VARCHAR(64);
ALTER TABLE execution_management_audit ADD COLUMN IF NOT EXISTS asset_before_revision VARCHAR(64);
ALTER TABLE execution_management_audit ADD COLUMN IF NOT EXISTS asset_after_revision VARCHAR(64);
-- One persistent monotonic policy revision avoids collisions between inherited layers.
CREATE TABLE IF NOT EXISTS execution_policy_revision (id BIGINT PRIMARY KEY, version BIGINT NOT NULL);
INSERT INTO execution_policy_revision(id,version) SELECT 1,0 WHERE NOT EXISTS (SELECT 1 FROM execution_policy_revision WHERE id=1);
-- Persist deployment defaults separately: restarting with new defaults must invalidate stale application claims.
CREATE TABLE IF NOT EXISTS execution_deployment_defaults (
    id BIGINT PRIMARY KEY,
    agent_json CLOB NOT NULL,
    policy_json CLOB NOT NULL,
    deployment_json CLOB NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_execution_agent_identity ON execution_agents(identity_hash);

-- Credential envelopes only; the deployment master key is never stored in this database.
-- Tombstones keep monotonic versions across delete/recreate and prevent stale preparation reuse.
CREATE TABLE IF NOT EXISTS execution_project_credentials (
    workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL, ref_id VARCHAR(256) NOT NULL,
    version BIGINT NOT NULL, key_id VARCHAR(128), nonce BINARY VARYING, ciphertext BINARY VARYING,
    PRIMARY KEY(workspace_id,project_id,ref_id)
);
CREATE TABLE IF NOT EXISTS execution_project_attachments (
    workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL, ref_id VARCHAR(256) NOT NULL,
    version BIGINT NOT NULL, kind VARCHAR(32) NOT NULL, hash VARCHAR(64) NOT NULL,
    size BIGINT NOT NULL, content BINARY LARGE OBJECT,
    PRIMARY KEY(workspace_id,project_id,ref_id)
);
ALTER TABLE execution_project_credentials ADD CONSTRAINT IF NOT EXISTS fk_execution_credentials_project
    FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE;
ALTER TABLE execution_project_attachments ADD CONSTRAINT IF NOT EXISTS fk_execution_attachments_project
    FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE;

-- One authoritative job/execution assignment; reports and release evidence are independent.
CREATE TABLE IF NOT EXISTS collaboration_policy (
    workspace_id BIGINT NOT NULL,
    project_id BIGINT NOT NULL,
    revision BIGINT NOT NULL,
    projection_revision BIGINT NOT NULL DEFAULT 1,
    settings_json CLOB NOT NULL,
    PRIMARY KEY(workspace_id,project_id)
);
ALTER TABLE collaboration_policy ADD COLUMN IF NOT EXISTS projection_revision BIGINT NOT NULL DEFAULT 1;
CREATE TABLE IF NOT EXISTS collaboration_policy_gate(id BIGINT PRIMARY KEY);
INSERT INTO collaboration_policy_gate(id) SELECT 1 WHERE NOT EXISTS(SELECT 1 FROM collaboration_policy_gate WHERE id=1);

-- Publication adapter declarations; no admission/intent/quota constraints are hidden in this baseline.
CREATE TABLE IF NOT EXISTS collaboration_previews (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id BIGINT,project_id BIGINT,actor_id BIGINT,state VARCHAR(32),
    source_json CLOB,access_json CLOB,policy_json CLOB,candidate_digest VARCHAR(64),body BLOB,
    created_at TIMESTAMP WITH TIME ZONE,expires_at TIMESTAMP WITH TIME ZONE,operation_deadline BIGINT,
    terminal_at_epoch_ms BIGINT,receipt_retire_at_epoch_ms BIGINT
);
ALTER TABLE collaboration_previews ADD COLUMN IF NOT EXISTS terminal_at_epoch_ms BIGINT;
ALTER TABLE collaboration_previews ADD COLUMN IF NOT EXISTS receipt_retire_at_epoch_ms BIGINT;
ALTER TABLE collaboration_previews ADD COLUMN IF NOT EXISTS purpose VARCHAR(32);
ALTER TABLE collaboration_previews ADD COLUMN IF NOT EXISTS source_kind VARCHAR(32);
CREATE TABLE IF NOT EXISTS collaboration_publications (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id BIGINT,project_id BIGINT,actor_id BIGINT,preview_id BIGINT,version BIGINT,
    publication_intent_id CLOB,kind VARCHAR(32),trust VARCHAR(32),digest VARCHAR(64),body BLOB,
    source_json CLOB,policy_json CLOB,format_version INTEGER,created_at TIMESTAMP WITH TIME ZONE
);
ALTER TABLE collaboration_publications ADD COLUMN IF NOT EXISTS revision BIGINT;
ALTER TABLE collaboration_publications ADD COLUMN IF NOT EXISTS enabled BOOLEAN;
ALTER TABLE collaboration_publications ADD COLUMN IF NOT EXISTS purpose VARCHAR(32);
ALTER TABLE collaboration_publications ADD COLUMN IF NOT EXISTS source_kind VARCHAR(32);
ALTER TABLE collaboration_publications ADD COLUMN IF NOT EXISTS source_revision CLOB;
ALTER TABLE collaboration_publications ADD COLUMN IF NOT EXISTS source_digest VARCHAR(64);
ALTER TABLE collaboration_publications ADD COLUMN IF NOT EXISTS source_upload_id BIGINT;
ALTER TABLE collaboration_publications ADD COLUMN IF NOT EXISTS source_uploaded_by BIGINT;
ALTER TABLE collaboration_publications ADD COLUMN IF NOT EXISTS source_job_id BIGINT;
ALTER TABLE collaboration_publications ADD COLUMN IF NOT EXISTS policy_epoch BIGINT;
UPDATE collaboration_publications SET revision=1 WHERE revision IS NULL;
UPDATE collaboration_publications SET enabled=CASE WHEN kind='mock' THEN FALSE ELSE TRUE END WHERE enabled IS NULL;
CREATE TABLE IF NOT EXISTS collaboration_publication_versions (
    workspace_id BIGINT,project_id BIGINT,next_version BIGINT,PRIMARY KEY(workspace_id,project_id)
);
CREATE TABLE IF NOT EXISTS collaboration_member_uploads (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id BIGINT,project_id BIGINT,actor_id BIGINT,kind VARCHAR(32),digest VARCHAR(64),
    body BLOB,created_at_epoch_ms BIGINT,expires_at_epoch_ms BIGINT
);
ALTER TABLE collaboration_member_uploads ADD COLUMN IF NOT EXISTS conclusion VARCHAR(32);
-- Canonical logical body/metadata charges and separately precharged owner release reservations.
CREATE TABLE IF NOT EXISTS collaboration_storage_accounts (
    workspace_id BIGINT,project_id BIGINT,actual_bytes BIGINT,reserved_bytes BIGINT,
    PRIMARY KEY(workspace_id,project_id)
);
ALTER TABLE collaboration_storage_accounts ADD COLUMN IF NOT EXISTS last_cleanup_epoch_ms BIGINT NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS collaboration_storage_objects (
    workspace_id BIGINT,project_id BIGINT,kind VARCHAR(32),object_id BIGINT,
    body_bytes BIGINT,metadata_json CLOB,metadata_bytes BIGINT,reserved_bytes BIGINT,pending BIGINT,inactive_since BIGINT,
    PRIMARY KEY(workspace_id,project_id,kind,object_id)
);
CREATE TABLE IF NOT EXISTS collaboration_storage_references (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id BIGINT,project_id BIGINT,target_kind VARCHAR(32),target_id BIGINT,
    owner_kind VARCHAR(32),owner_id BIGINT,expires_at BIGINT
);
CREATE TABLE IF NOT EXISTS collaboration_management_audit (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id BIGINT,project_id BIGINT,event_json CLOB,created_at_epoch_ms BIGINT
);
ALTER TABLE collaboration_management_audit ADD COLUMN IF NOT EXISTS retention_class VARCHAR(16) NOT NULL DEFAULT 'management';

CREATE TABLE IF NOT EXISTS collaboration_mock_logs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,publication_id BIGINT NOT NULL,
    metadata_json CLOB NOT NULL,created_at_epoch_ms BIGINT NOT NULL
);
CREATE TABLE IF NOT EXISTS collaboration_mock_log_state (
    publication_id BIGINT PRIMARY KEY,workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,discarded BIGINT NOT NULL
);

CREATE TABLE IF NOT EXISTS collaboration_grants (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,publication_id BIGINT NOT NULL,version BIGINT NOT NULL,
    purpose VARCHAR(16) NOT NULL,audience VARCHAR(16) NOT NULL,responsible_id BIGINT NOT NULL,responsibility_epoch BIGINT NOT NULL,
    public_id VARCHAR(32) UNIQUE,key_hash VARBINARY(32),generation BIGINT NOT NULL,
    created_at BIGINT NOT NULL,expires_at BIGINT NOT NULL,state VARCHAR(16) NOT NULL,reason VARCHAR(32),ended_at BIGINT,
    download_allowed BOOLEAN NOT NULL,revision BIGINT NOT NULL,operation_intent VARCHAR(128) NOT NULL
);
CREATE TABLE IF NOT EXISTS collaboration_grant_operations (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,operation_intent VARCHAR(128) NOT NULL,
    actor_id BIGINT NOT NULL,grant_id BIGINT NOT NULL,command VARCHAR(16) NOT NULL,fingerprint VARCHAR(64) NOT NULL,
    revision BIGINT NOT NULL,generation BIGINT NOT NULL,
    UNIQUE(workspace_id,project_id,operation_intent)
);
CREATE TABLE IF NOT EXISTS collaboration_deployment_policy_applied (
    id BIGINT PRIMARY KEY,digest VARCHAR(64) NOT NULL,applied_at BIGINT NOT NULL
);

CREATE TABLE IF NOT EXISTS execution_jobs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    execution_id BIGINT NOT NULL UNIQUE,
    workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL, submitted_by BIGINT NOT NULL,
    agent_id BIGINT NOT NULL, snapshot_id BIGINT NOT NULL, intent_id VARCHAR(512) NOT NULL,
    intent_hash VARCHAR(64) NOT NULL, submission_json CLOB NOT NULL, task_json CLOB NOT NULL,
    inputs_json CLOB NOT NULL, inputs_digest VARCHAR(64) NOT NULL,
    state VARCHAR(16) NOT NULL DEFAULT 'queued', accepted BOOLEAN NOT NULL DEFAULT FALSE,
    cancel_state VARCHAR(16) NOT NULL DEFAULT 'none', execution_released BOOLEAN NOT NULL DEFAULT FALSE,
    permit_id BIGINT, permit_json CLOB, progress_sequence BIGINT NOT NULL DEFAULT 0, progress_json CLOB,
    summary_json CLOB, report_hash VARCHAR(64), report_bytes BIGINT, report_content BINARY LARGE OBJECT,
    reserved_input_bytes BIGINT NOT NULL DEFAULT 0, reserved_result_bytes BIGINT NOT NULL DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    queue_expires_at TIMESTAMP WITH TIME ZONE,
    UNIQUE(submitted_by,project_id,intent_id)
);
CREATE TABLE IF NOT EXISTS execution_job_messages (
    agent_id BIGINT NOT NULL, message_id VARCHAR(512) NOT NULL, payload_hash VARCHAR(64) NOT NULL,
    job_id BIGINT NOT NULL, execution_id BIGINT NOT NULL, PRIMARY KEY(agent_id,message_id)
);
CREATE TABLE IF NOT EXISTS execution_stress_reservations (
    job_id BIGINT PRIMARY KEY REFERENCES execution_jobs(id) ON DELETE CASCADE,
    agent_id BIGINT NOT NULL, jobs BIGINT NOT NULL, processes BIGINT NOT NULL, vus BIGINT NOT NULL,
    request_concurrency BIGINT NOT NULL, max_rps DOUBLE PRECISION NOT NULL, metric_memory_bytes BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS execution_stress_agent ON execution_stress_reservations(agent_id);
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS capacity_wait_reason VARCHAR(64);
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS stress_metadata_json CLOB;
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS report_kind VARCHAR(32);
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS report_verdict VARCHAR(32);
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS terminal_conclusion VARCHAR(32);
-- Server-only immutable scheduling origin; never part of TaskEnvelope or public Submit.
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS schedule_occurrence_id BIGINT;
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS schedule_id BIGINT;
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS schedule_revision BIGINT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_execution_jobs_schedule_occurrence ON execution_jobs(schedule_occurrence_id);
ALTER TABLE execution_jobs ADD CONSTRAINT IF NOT EXISTS ck_execution_jobs_schedule_origin CHECK (
    (schedule_occurrence_id IS NULL AND schedule_id IS NULL AND schedule_revision IS NULL) OR
    (schedule_occurrence_id IS NOT NULL AND schedule_id IS NOT NULL AND schedule_revision IS NOT NULL
     AND schedule_occurrence_id>0 AND schedule_id>0 AND schedule_revision>0)
);
CREATE TABLE IF NOT EXISTS execution_job_outbox (
    message_id VARCHAR(512) PRIMARY KEY, agent_id BIGINT NOT NULL, job_id BIGINT,
    execution_id BIGINT, kind VARCHAR(32) NOT NULL, payload_json CLOB NOT NULL,
    acknowledged BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE TABLE IF NOT EXISTS execution_job_ids (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY);
CREATE TABLE IF NOT EXISTS execution_debug_sessions (
    handle VARCHAR(128) PRIMARY KEY, workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL,
    owner_id BIGINT NOT NULL, agent_id BIGINT NOT NULL, expires_at TIMESTAMP WITH TIME ZONE NOT NULL
);
CREATE TABLE IF NOT EXISTS execution_agent_control_state (
    agent_id BIGINT PRIMARY KEY, session_id VARCHAR(512) NOT NULL,
    applied_config_version VARCHAR(32) NOT NULL,
    last_seen TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS execution_schedule_grants (
    workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,version BIGINT NOT NULL,user_ids_json CLOB NOT NULL,
    PRIMARY KEY(workspace_id,project_id)
);
-- H2 CURRENT_TIMESTAMP is transaction-frozen. This fixed, non-DETERMINISTIC alias runs in the database engine.
CREATE ALIAS IF NOT EXISTS APICC_SCHEDULER_EPOCH_MILLIS FOR 'java.lang.System.currentTimeMillis';
CREATE TABLE IF NOT EXISTS execution_schedule_capacity_lock (id BIGINT PRIMARY KEY);
INSERT INTO execution_schedule_capacity_lock(id) SELECT 1 WHERE NOT EXISTS (SELECT 1 FROM execution_schedule_capacity_lock WHERE id=1);
CREATE TABLE IF NOT EXISTS execution_schedules (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,subject_user_id BIGINT NOT NULL,
    name VARCHAR(128) NOT NULL,version BIGINT NOT NULL DEFAULT 1,revision BIGINT NOT NULL DEFAULT 1,
    cancellation_version BIGINT NOT NULL DEFAULT 0,enabled BOOLEAN NOT NULL DEFAULT FALSE,deleted BOOLEAN NOT NULL DEFAULT FALSE,
    notifications_json CLOB NOT NULL,paused_reason_code VARCHAR(96) DEFAULT 'schedule-paused',
    next_planned_at_utc TIMESTAMP WITH TIME ZONE,evaluated_through_utc TIMESTAMP WITH TIME ZONE,
    last_admitted_planned_at_utc TIMESTAMP WITH TIME ZONE
);
ALTER TABLE execution_schedules ADD COLUMN IF NOT EXISTS evaluation_anchor_utc TIMESTAMP WITH TIME ZONE;
-- Upgrade scheduling-only timestamps without changing original Job storage or claiming recovery of previously rounded values.
ALTER TABLE execution_schedules ALTER COLUMN next_planned_at_utc TIMESTAMP(9) WITH TIME ZONE;
ALTER TABLE execution_schedules ALTER COLUMN evaluated_through_utc TIMESTAMP(9) WITH TIME ZONE;
ALTER TABLE execution_schedules ALTER COLUMN last_admitted_planned_at_utc TIMESTAMP(9) WITH TIME ZONE;
ALTER TABLE execution_schedules ALTER COLUMN evaluation_anchor_utc TIMESTAMP(9) WITH TIME ZONE;
CREATE INDEX IF NOT EXISTS execution_schedules_project ON execution_schedules(workspace_id,project_id,id);
CREATE TABLE IF NOT EXISTS execution_schedule_revisions (
    workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,schedule_id BIGINT NOT NULL,revision BIGINT NOT NULL,
    subject_user_id BIGINT NOT NULL,rule_json CLOB NOT NULL,policies_json CLOB NOT NULL,execution_json CLOB NOT NULL,
    snapshot_version VARCHAR(32) NOT NULL,manifest_hash VARCHAR(64) NOT NULL,
    PRIMARY KEY(workspace_id,project_id,schedule_id,revision)
);
CREATE INDEX IF NOT EXISTS execution_schedules_due ON execution_schedules(next_planned_at_utc,id);
CREATE TABLE IF NOT EXISTS execution_schedule_occurrences (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,schedule_id BIGINT NOT NULL,
    revision BIGINT NOT NULL,cancellation_version BIGINT NOT NULL,subject_user_id BIGINT NOT NULL,
    planned_at_utc TIMESTAMP(9) WITH TIME ZONE NOT NULL,observed_at_utc TIMESTAMP(9) WITH TIME ZONE NOT NULL,
    queue_deadline_utc TIMESTAMP(9) WITH TIME ZONE NOT NULL,
    state VARCHAR(32) NOT NULL,reason_code VARCHAR(96),materials_json CLOB,
    owner_id VARCHAR(128),generation BIGINT,lease_until_utc TIMESTAMP(9) WITH TIME ZONE,
    job_id BIGINT UNIQUE,execution_id BIGINT,terminal_at_utc TIMESTAMP(9) WITH TIME ZONE,
    UNIQUE(schedule_id,planned_at_utc)
);
ALTER TABLE execution_schedule_occurrences ALTER COLUMN planned_at_utc TIMESTAMP(9) WITH TIME ZONE;
ALTER TABLE execution_schedule_occurrences ALTER COLUMN observed_at_utc TIMESTAMP(9) WITH TIME ZONE;
ALTER TABLE execution_schedule_occurrences ALTER COLUMN queue_deadline_utc TIMESTAMP(9) WITH TIME ZONE;
ALTER TABLE execution_schedule_occurrences ALTER COLUMN lease_until_utc TIMESTAMP(9) WITH TIME ZONE;
ALTER TABLE execution_schedule_occurrences ALTER COLUMN terminal_at_utc TIMESTAMP(9) WITH TIME ZONE;
CREATE INDEX IF NOT EXISTS execution_schedule_occurrences_recovery ON execution_schedule_occurrences(state,id);
ALTER TABLE execution_schedule_occurrences ADD COLUMN IF NOT EXISTS notification_processed_version BIGINT NOT NULL DEFAULT 0;
ALTER TABLE execution_schedules ADD COLUMN IF NOT EXISTS notification_processed_version BIGINT NOT NULL DEFAULT 0;
-- NULL deliberately preserves unknown pre-notification pause provenance; new authority writes set the real version.
ALTER TABLE execution_schedules ADD COLUMN IF NOT EXISTS notification_pause_source_version BIGINT;
CREATE TABLE IF NOT EXISTS execution_notification_gate(id BIGINT PRIMARY KEY);
INSERT INTO execution_notification_gate(id) SELECT 1 WHERE NOT EXISTS(SELECT 1 FROM execution_notification_gate WHERE id=1);
CREATE TABLE IF NOT EXISTS execution_notification_events (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,
    source_id VARCHAR(96) NOT NULL,source_version BIGINT NOT NULL,event_kind VARCHAR(16) NOT NULL,
    body_json CLOB,created_at TIMESTAMP WITH TIME ZONE NOT NULL,in_app BOOLEAN NOT NULL DEFAULT TRUE,
    UNIQUE(source_id,event_kind,source_version)
);
CREATE TABLE IF NOT EXISTS execution_notification_reads (
    event_id BIGINT NOT NULL,user_id BIGINT NOT NULL,PRIMARY KEY(event_id,user_id)
);
ALTER TABLE execution_notification_events ADD COLUMN IF NOT EXISTS schedule_id BIGINT;
ALTER TABLE execution_notification_events ADD COLUMN IF NOT EXISTS reason_code VARCHAR(96);
CREATE INDEX IF NOT EXISTS execution_notification_schedule ON execution_notification_events(workspace_id,project_id,schedule_id,id);
CREATE TABLE IF NOT EXISTS execution_notification_channels (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,workspace_id BIGINT NOT NULL,
    name VARCHAR(128) NOT NULL,version BIGINT NOT NULL DEFAULT 1,enabled BOOLEAN NOT NULL,deleted BOOLEAN NOT NULL DEFAULT FALSE,
    origin VARCHAR(512) NOT NULL,key_id VARCHAR(128),nonce VARBINARY(12),ciphertext VARBINARY(16384),limits_json CLOB
);
CREATE TABLE IF NOT EXISTS execution_notification_outbox (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_id BIGINT NOT NULL,workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,
    channel_id BIGINT NOT NULL,channel_version BIGINT NOT NULL,body_json CLOB,body_hash VARCHAR(64) NOT NULL,limits_json CLOB,
    deadline_utc TIMESTAMP WITH TIME ZONE NOT NULL,next_attempt_at TIMESTAMP WITH TIME ZONE,state VARCHAR(32) NOT NULL DEFAULT 'pending',
    attempts INTEGER NOT NULL DEFAULT 0,owner_id VARCHAR(128),lease_token VARCHAR(64),lease_until_utc TIMESTAMP WITH TIME ZONE,
    reason_code VARCHAR(96),http_status INTEGER,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    UNIQUE(event_id,channel_id,channel_version)
);
CREATE INDEX IF NOT EXISTS execution_notification_due ON execution_notification_outbox(state,next_attempt_at,id);
CREATE TABLE IF NOT EXISTS execution_schedule_missed_windows (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,schedule_id BIGINT NOT NULL,revision BIGINT NOT NULL,
    from_utc TIMESTAMP(9) WITH TIME ZONE NOT NULL,through_utc TIMESTAMP(9) WITH TIME ZONE NOT NULL,
    observed_at_utc TIMESTAMP(9) WITH TIME ZONE NOT NULL,reason_code VARCHAR(96) NOT NULL,
    missed_count BIGINT,UNIQUE(schedule_id,from_utc,through_utc)
);
ALTER TABLE execution_schedule_missed_windows ALTER COLUMN from_utc TIMESTAMP(9) WITH TIME ZONE;
ALTER TABLE execution_schedule_missed_windows ALTER COLUMN through_utc TIMESTAMP(9) WITH TIME ZONE;
ALTER TABLE execution_schedule_missed_windows ALTER COLUMN observed_at_utc TIMESTAMP(9) WITH TIME ZONE;
CREATE INDEX IF NOT EXISTS execution_schedule_missed_history ON execution_schedule_missed_windows(schedule_id,id);
CREATE TABLE IF NOT EXISTS execution_scheduler_control (
    id BIGINT PRIMARY KEY,mode VARCHAR(16),generation BIGINT NOT NULL DEFAULT 1,version BIGINT NOT NULL DEFAULT 1
);
INSERT INTO execution_scheduler_control(id) SELECT 1 WHERE NOT EXISTS (SELECT 1 FROM execution_scheduler_control WHERE id=1);
CREATE TABLE IF NOT EXISTS execution_agent_runtime (
    agent_id BIGINT PRIMARY KEY, session_id VARCHAR(512) NOT NULL, description_json CLOB NOT NULL
);
ALTER TABLE execution_debug_sessions ADD COLUMN IF NOT EXISTS host_session_id VARCHAR(512);
ALTER TABLE execution_debug_sessions ADD COLUMN IF NOT EXISTS server_id VARCHAR(2048);
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS runtime_session_id VARCHAR(512);
-- Result transfer is independent of execution release; no hash is not proof of no pending result.
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS report_state VARCHAR(16) NOT NULL DEFAULT 'none';
-- Unknown historical archive times are conservatively anchored by the bounded cleanup consumer.
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS report_retained_at TIMESTAMP WITH TIME ZONE;
CREATE INDEX IF NOT EXISTS execution_result_retention ON execution_jobs(report_state,project_id,report_retained_at);
UPDATE execution_jobs SET report_state='archived' WHERE report_content IS NOT NULL AND report_state<>'archived';
UPDATE execution_jobs SET report_state='pending' WHERE report_content IS NULL AND report_state='none'
    AND (state IN ('preparing','running') OR report_hash IS NOT NULL);

-- F7g synchronization side tables. CREATE IF NOT EXISTS is additive and preserves old projects/ACL/assets.
-- Sync revisions are canonical decimal text (unbounded by Java long); asset versions keep their existing BIGINT contract.
CREATE TABLE IF NOT EXISTS sync_sources (
    workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,id VARCHAR(36) NOT NULL,
    source_revision CLOB NOT NULL,source_json CLOB NOT NULL,deleted BOOLEAN NOT NULL DEFAULT FALSE,
    mapping_revision CLOB DEFAULT '0' NOT NULL,baseline_revision CLOB DEFAULT '0' NOT NULL,
    mapping_json CLOB,baseline_json CLOB,baseline_bytes BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY(workspace_id,project_id,id)
);
CREATE TABLE IF NOT EXISTS sync_checks (
    workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,id VARCHAR(36) NOT NULL,source_id VARCHAR(36) NOT NULL,
    source_revision CLOB NOT NULL,subject_user_id BIGINT NOT NULL,state VARCHAR(32) NOT NULL,
    details_json CLOB,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY(workspace_id,project_id,id)
);
ALTER TABLE sync_checks ADD COLUMN IF NOT EXISTS admission_after TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE sync_checks ADD COLUMN IF NOT EXISTS owner_id VARCHAR(36);
ALTER TABLE sync_checks ADD COLUMN IF NOT EXISTS ownership_token VARCHAR(36);
ALTER TABLE sync_checks ADD COLUMN IF NOT EXISTS lease_until_utc TIMESTAMP(9) WITH TIME ZONE;
CREATE INDEX IF NOT EXISTS sync_check_dispatch ON sync_checks(state,admission_after,created_at);
CREATE INDEX IF NOT EXISTS sync_check_expired_ownership ON sync_checks(state,lease_until_utc);
CREATE INDEX IF NOT EXISTS sync_check_source_status ON sync_checks(workspace_id,project_id,source_id,state,created_at);
CREATE TABLE IF NOT EXISTS sync_candidates (
    workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,id VARCHAR(36) NOT NULL,source_id VARCHAR(36) NOT NULL,
    fixed_json CLOB NOT NULL,content_bytes BIGINT NOT NULL DEFAULT 0,reference_count BIGINT NOT NULL DEFAULT 1,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY(workspace_id,project_id,id)
);
CREATE TABLE IF NOT EXISTS sync_history (
    workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,id VARCHAR(36) NOT NULL,source_id VARCHAR(36) NOT NULL,
    history_json CLOB NOT NULL,before_content CLOB NOT NULL,after_content CLOB NOT NULL,
    content_bytes BIGINT NOT NULL DEFAULT 0,reference_count BIGINT NOT NULL DEFAULT 1,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY(workspace_id,project_id,id)
);
CREATE TABLE IF NOT EXISTS sync_operations (
    workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,intent_id VARCHAR(36) NOT NULL,
    actor_id BIGINT NOT NULL,kind VARCHAR(32) NOT NULL,request_hash VARCHAR(64) NOT NULL,response_json CLOB NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY(workspace_id,project_id,intent_id)
);
CREATE TABLE IF NOT EXISTS sync_policies (
    workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,revision CLOB NOT NULL,policy_json CLOB NOT NULL,
    PRIMARY KEY(workspace_id,project_id)
);

-- Online retention owners are host metadata; public T1 history/receipt bytes stay immutable.
ALTER TABLE sync_sources ADD COLUMN IF NOT EXISTS current_history_id VARCHAR(36);
ALTER TABLE sync_history ADD COLUMN IF NOT EXISTS active_owners_json CLOB DEFAULT '[]' NOT NULL;
ALTER TABLE sync_sources ADD COLUMN IF NOT EXISTS baseline_ref_json CLOB;
ALTER TABLE sync_sources ADD COLUMN IF NOT EXISTS schedule_json CLOB;
CREATE TABLE IF NOT EXISTS sync_occurrences (
    workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,id VARCHAR(36) NOT NULL,source_id VARCHAR(36) NOT NULL,
    generation CLOB NOT NULL,planned_at_utc VARCHAR(40) NOT NULL,trigger_key VARCHAR(64) NOT NULL,state VARCHAR(32) NOT NULL,check_id VARCHAR(36),details_json CLOB NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY(workspace_id,project_id,id),UNIQUE(workspace_id,project_id,trigger_key)
);
